macro_rules! deps {
    () => {
        SecondsSinceUnixEpoch!();
        OffsetInSeconds!();
        Error!();
        Time!();
        Format!();
    };
}

macro_rules! function {
    () => {
        deps!();
        pub (crate) mod function { use std :: { str :: FromStr , time :: SystemTime } ; use jiff :: { civil :: Date , fmt :: rfc2822 , tz :: TimeZone , Zoned } ; use crate :: { parse :: { relative , Error } , time :: format :: { DEFAULT , GITOXIDE , ISO8601 , ISO8601_STRICT , SHORT } , OffsetInSeconds , SecondsSinceUnixEpoch , Time , } ; # [doc = " Parse `input` as any time that Git can parse when inputting a date."] # [doc = ""] # [doc = " ## Examples"] # [doc = ""] # [doc = " ### 1. SHORT Format"] # [doc = ""] # [doc = " *   `2018-12-24`"] # [doc = " *   `1970-01-01`"] # [doc = " *   `1950-12-31`"] # [doc = " *   `2024-12-31`"] # [doc = ""] # [doc = " ### 2. RFC2822 Format"] # [doc = ""] # [doc = " *   `Thu, 18 Aug 2022 12:45:06 +0800`"] # [doc = " *   `Mon Oct 27 10:30:00 2023 -0800`"] # [doc = ""] # [doc = " ### 3. GIT_RFC2822 Format"] # [doc = ""] # [doc = " *   `Thu, 8 Aug 2022 12:45:06 +0800`"] # [doc = " *   `Mon Oct 27 10:30:00 2023 -0800` (Note the single-digit day)"] # [doc = ""] # [doc = " ### 4. ISO8601 Format"] # [doc = ""] # [doc = " *   `2022-08-17 22:04:58 +0200`"] # [doc = " *   `1970-01-01 00:00:00 -0500`"] # [doc = ""] # [doc = " ### 5. ISO8601_STRICT Format"] # [doc = ""] # [doc = " *   `2022-08-17T21:43:13+08:00`"] # [doc = ""] # [doc = " ### 6. UNIX Timestamp (Seconds Since Epoch)"] # [doc = ""] # [doc = " *   `123456789`"] # [doc = " *   `0` (January 1, 1970 UTC)"] # [doc = " *   `-1000`"] # [doc = " *   `1700000000`"] # [doc = ""] # [doc = " ### 7. Commit Header Format"] # [doc = ""] # [doc = " *   `1745582210 +0200`"] # [doc = " *   `1660874655 +0800`"] # [doc = " *   `-1660874655 +0800`"] # [doc = ""] # [doc = " See also the [`parse_header()`]."] # [doc = ""] # [doc = " ### 8. GITOXIDE Format"] # [doc = ""] # [doc = " *   `Thu Sep 04 2022 10:45:06 -0400`"] # [doc = " *   `Mon Oct 27 2023 10:30:00 +0000`"] # [doc = ""] # [doc = " ### 9. DEFAULT Format"] # [doc = ""] # [doc = " *   `Thu Sep 4 10:45:06 2022 -0400`"] # [doc = " *   `Mon Oct 27 10:30:00 2023 +0000`"] # [doc = ""] # [doc = " ### 10. Relative Dates (e.g., \"2 minutes ago\", \"1 hour from now\")"] # [doc = ""] # [doc = " These dates are parsed *relative to a `now` timestamp*. The examples depend entirely on the value of `now`."] # [doc = " If `now` is October 27, 2023 at 10:00:00 UTC:"] # [doc = "     *   `2 minutes ago` (October 27, 2023 at 09:58:00 UTC)"] # [doc = "     *   `3 hours ago` (October 27, 2023 at 07:00:00 UTC)"] pub fn parse (input : & str , now : Option < SystemTime >) -> Result < Time , Error > { Ok (if let Ok (val) = Date :: strptime (SHORT . 0 , input) { let val = val . to_zoned (TimeZone :: UTC) . map_err (| _ | Error :: InvalidDateString { input : input . into () }) ? ; Time :: new (val . timestamp () . as_second () , val . offset () . seconds ()) } else if let Ok (val) = rfc2822_relaxed (input) { Time :: new (val . timestamp () . as_second () , val . offset () . seconds ()) } else if let Ok (val) = strptime_relaxed (ISO8601 . 0 , input) { Time :: new (val . timestamp () . as_second () , val . offset () . seconds ()) } else if let Ok (val) = strptime_relaxed (ISO8601_STRICT . 0 , input) { Time :: new (val . timestamp () . as_second () , val . offset () . seconds ()) } else if let Ok (val) = strptime_relaxed (GITOXIDE . 0 , input) { Time :: new (val . timestamp () . as_second () , val . offset () . seconds ()) } else if let Ok (val) = strptime_relaxed (DEFAULT . 0 , input) { Time :: new (val . timestamp () . as_second () , val . offset () . seconds ()) } else if let Ok (val) = SecondsSinceUnixEpoch :: from_str (input) { Time :: new (val , 0) } else if let Some (val) = relative :: parse (input , now) . transpose () ? { Time :: new (val . timestamp () . as_second () , val . offset () . seconds ()) } else if let Some (val) = parse_raw (input) { val } else { return Err (Error :: InvalidDateString { input : input . into () }) ; }) } # [doc = " Unlike [`parse()`] which handles all kinds of input, this function only parses the commit-header format"] # [doc = " like `1745582210 +0200`."] # [doc = ""] # [doc = " Note that failure to parse the time zone isn't fatal, instead it will default to `0`. To know if"] # [doc = " the time is wonky, serialize the return value to see if it matches the `input.`"] pub fn parse_header (input : & str) -> Option < Time > { pub enum Sign { Plus , Minus , } fn parse_offset (offset : & str) -> Option < OffsetInSeconds > { if (offset . len () != 5) && (offset . len () != 7) { return None ; } let sign = match offset . get (.. 1) ? { "-" => Some (Sign :: Minus) , "+" => Some (Sign :: Plus) , _ => None , } ? ; if offset . as_bytes () . get (1) . is_some_and (| b | ! b . is_ascii_digit ()) { return None ; } let hours : i32 = offset . get (1 .. 3) ? . parse () . ok () ? ; let minutes : i32 = offset . get (3 .. 5) ? . parse () . ok () ? ; let offset_seconds : i32 = if offset . len () == 7 { offset . get (5 .. 7) ? . parse () . ok () ? } else { 0 } ; let mut offset_in_seconds = hours * 3600 + minutes * 60 + offset_seconds ; if matches ! (sign , Sign :: Minus) { offset_in_seconds *= - 1 ; } Some (offset_in_seconds) } if input . contains (':') { return None ; } let mut split = input . split_whitespace () ; let seconds = split . next () ? ; let seconds = match seconds . parse :: < SecondsSinceUnixEpoch > () { Ok (s) => s , Err (_err) => { let first_digits : String = seconds . chars () . take_while (char :: is_ascii_digit) . collect () ; first_digits . parse () . ok () ? } } ; let offset = match split . next () { None => 0 , Some (offset) => { if split . next () . is_some () { 0 } else { parse_offset (offset) . unwrap_or_default () } } } ; let time = Time { seconds , offset } ; Some (time) } # [doc = " Strictly parse the raw commit header format like `1745582210 +0200`."] # [doc = ""] # [doc = " Some strict rules include:"] # [doc = ""] # [doc = " - The timezone offset must be present."] # [doc = " - The timezone offset must have a sign; either `+` or `-`."] # [doc = " - The timezone offset hours must be less than or equal to 14."] # [doc = " - The timezone offset minutes must be exactly 0, 15, 30, or 45."] # [doc = " - The timezone offset seconds may be present, but 0 is the only valid value."] # [doc = " - Only whitespace may suffix the timezone offset."] # [doc = ""] # [doc = " But this function isn't perfectly strict insofar as it allows arbitrary"] # [doc = " whitespace before and after the seconds and offset components."] # [doc = ""] # [doc = " The goal is to only accept inputs that _unambiguously_ look like"] # [doc = " git's raw date format."] fn parse_raw (input : & str) -> Option < Time > { let mut split = input . split_whitespace () ; let seconds = split . next () ? . parse :: < SecondsSinceUnixEpoch > () . ok () ? ; let offset_str = split . next () ? ; if split . next () . is_some () { return None ; } let offset_len = offset_str . len () ; if offset_len != 5 && offset_len != 7 { return None ; } let sign : i32 = match offset_str . get (.. 1) ? { "-" => Some (- 1) , "+" => Some (1) , _ => None , } ? ; let hours : u8 = offset_str . get (1 .. 3) ? . parse () . ok () ? ; let minutes : u8 = offset_str . get (3 .. 5) ? . parse () . ok () ? ; let offset_seconds : u8 = if offset_len == 7 { offset_str . get (5 .. 7) ? . parse () . ok () ? } else { 0 } ; if hours > 14 || (minutes != 0 && minutes != 15 && minutes != 30 && minutes != 45) || offset_seconds != 0 { return None ; } let offset : i32 = sign * ((hours as i32) * 3600 + (minutes as i32) * 60) ; Time { seconds , offset } . into () } # [doc = " This is just like `Zoned::strptime`, but it allows parsing datetimes"] # [doc = " whose weekdays are inconsistent with the date. While the day-of-week"] # [doc = " still must be parsed, it is otherwise ignored. This seems to be"] # [doc = " consistent with how `git` behaves."] fn strptime_relaxed (fmt : & str , input : & str) -> Result < Zoned , jiff :: Error > { let mut tm = jiff :: fmt :: strtime :: parse (fmt , input) ? ; tm . set_weekday (None) ; tm . to_zoned () } # [doc = " This is just like strptime_relaxed, except for RFC 2822 parsing."] # [doc = " Namely, it permits the weekday to be inconsistent with the date."] fn rfc2822_relaxed (input : & str) -> Result < Zoned , jiff :: Error > { static P : rfc2822 :: DateTimeParser = rfc2822 :: DateTimeParser :: new () . relaxed_weekday (true) ; P . parse_zoned (input) } # [cfg (test)] mod tests { use super :: * ; # [test] fn parse_raw_valid () { for (valid , expected_seconds , expected_offset) in [("12345 +0000" , 12345 , 0) , ("-1234567 +0000" , - 1234567 , 0) , ("+1234567 -000000" , 1234567 , 0) , ("   +0    -000000    " , 0 , 0) , ("\t-0\t-0000\t" , 0 , 0) , ("\n-0\r\n-0000\n" , 0 , 0) ,] { assert_eq ! (parse_raw (valid) , Some (Time { seconds : expected_seconds , offset : expected_offset }) , "should succeed: '{valid}'") ; } } # [test] fn parse_raw_invalid () { for (bad_date_str , message) in [("123456 !0600" , "invalid sign - must be + or -") , ("123456 0600" , "missing offset sign") , ("123456 +060" , "positive offset too short") , ("123456 -060" , "negative offset too short") , ("123456 +06000" , "not enough offset seconds") , ("123456 --060" , "duplicate offset sign with correct offset length") , ("123456 -+060" , "multiple offset signs with correct offset length") , ("123456 --0600" , "multiple offset signs, but incorrect offset length") , ("123456 +-06000" , "multiple offset signs with correct offset length") , ("123456 +-0600" , "multiple offset signs with incorrect offset length") , ("123456 +-060" , "multiple offset signs with correct offset length") , ("123456 +10030" , "invalid offset length with one 'second' field") , ("123456 06000" , "invalid offset length, missing sign") , ("123456 +0600 extra" , "extra field past offset") , ("123456 +0600 2005" , "extra field past offset that looks like year") , ("123456+0600" , "missing space between unix timestamp and offset") , ("123456 + 600" , "extra spaces between sign and offset (which also is too short)" ,) , ("123456 -1500" , "negative offset hours out of bounds") , ("123456 +1500" , "positive offset hours out of bounds") , ("123456 +6600" , "positive offset hours out of bounds") , ("123456 +0660" , "invalid offset minutes") , ("123456 +060010" , "positive offset seconds is allowed but only if zero") , ("123456 -060010" , "negative offset seconds is allowed but only if zero") , ("123456 +0075" , "positive offset minutes invalid") , ("++123456 +0000" , "duplicate timestamp sign") , ("--123456 +0000" , "duplicate timestamp sign") , ("1234567 -+1+1+0" , "unsigned offset parsing rejects '+'") ,] { assert ! (parse_raw (bad_date_str) . is_none () , "should fail: '{bad_date_str}': {message}") ; } } } }
    };
}

function!();